tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const rows = JSON.parse(readFileSync('work/rows.json', 'utf8'));
const toDto = value => ({ unit: 'EUR-cent', value: value.toString() });
const settlement = rows.map(({ id, unitMinor, quantity, kind }) => {
  assert(Number.isSafeInteger(quantity));
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, 'floor');
  if (kind === 'standard') {
    return { id, net: toDto(net), fee: toDto(mulDivMinor(net, 1n, 10n, 'floor')) };
  }
  assert.equal(kind, 'manual');
  return {
    id,
    net: toDto(net),
    fee: null,
    status: 'blocked',
    requiredDecision: 'Марине, владельцу расчётов, необходимо утвердить ставку сбора и правило округления для вида manual.'
  };
});

const json = JSON.stringify(settlement, null, 2) + '\\n';
const decoded = JSON.parse(json);
assert.deepEqual(decoded.map(row => row.id), rows.map(row => row.id));
const readDto = dto => {
  assert.deepEqual(Object.keys(dto).sort(), ['unit', 'value']);
  assert.equal(dto.unit, 'EUR-cent');
  return readMinor(dto.value);
};
assert.deepEqual(decoded.map(row => [readDto(row.net), row.fee === null ? null : readDto(row.fee)]),
  [[-3n, -1n], [38n, 3n], [22n, null]]);
assert.equal(decoded[2].status, 'blocked');
writeFileSync('settlement.json', json, { flag: 'wx' });
assert.equal(readFileSync('settlement.json', 'utf8'), json);
NODE
cat settlement.json"

